const BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:8080";

export class LocaisService {
    static async getAll() {
        const res = await fetch(`${BASE_URL}/api/local/all`);
        if (!res.ok) throw new Error(`Erro ao buscar locais (${res.status})`);
        return res.json();
    }

    static async create(payload) {
        const res = await fetch(`${BASE_URL}/api/local`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload),
        });
        if (!res.ok) {
            const body = await res.text();
            throw new Error(`Erro ao criar local (${res.status}): ${body}`);
        }
        return res.json();
    }

    static async update(id, payload) {
        const res = await fetch(`${BASE_URL}/api/local/${id}`, {
            method: "PUT",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload),
        });
        if (!res.ok) {
            const body = await res.text();
            throw new Error(`Erro ao atualizar local (${res.status}): ${body}`);
        }
        return res.json();
    }

    static async delete(id) {
        const res = await fetch(`${BASE_URL}/api/local/${id}`, {
            method: "DELETE",
        });
        if (!res.ok) throw new Error(`Erro ao deletar local (${res.status})`);
    }
}
